changeSet.sql:
ALTER TABLE modeling_model_spec
    DROP CONSTRAINT ck_model_spec_dimension_definition_ref;
ALTER TABLE modeling_model_spec
    ADD CONSTRAINT ck_model_spec_dimension_definition_ref
    CHECK (
        contract_version = 2
        AND (
            (
                model_type = 'DIMENSION'
                AND dimension_definition_id IS NOT NULL
                AND dimension_definition_revision IS NOT NULL
            )
            OR (
                model_type <> 'DIMENSION'
                AND dimension_definition_id IS NULL
                AND dimension_definition_revision IS NULL
            )
        )
    );

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_DIMENSION_DEFINITION_LEGACY_MIGRATION_RETIREMENT_FORWARD_ONLY: recovery requires a new forward changeset';
END $$;
